@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    ParseContext that = (ParseContext) o;
    if (!context.equals(that.context)) {
        return false;
    }
    return jsonConfigs.equals(that.jsonConfigs);
}
